#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

namespace AvianVoice.Editor
{
    /// <summary>
    /// Import settings for MakeHuman (MPFB2) avatars under Resources/Avatars/MakeHuman, generated by
    /// Tools/MakeHuman/generate_neutral_avatar.py: Humanoid rig from the mixamo_unity bones, opaque skin and
    /// clothes, alpha-clipped hair / eyebrows / eyelashes, glossy eyes.
    /// </summary>
    public class MakeHumanAvatarImport : AssetPostprocessor
    {
        public const string RootFolder = "Assets/AvianVoice/Resources/Avatars/MakeHuman/";

        bool Applies => assetPath.Replace('\\', '/').StartsWith(RootFolder);

        void OnPreprocessModel()
        {
            if (!Applies)
                return;

            var importer = (ModelImporter)assetImporter;
            importer.animationType = ModelImporterAnimationType.Human;
            importer.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
            importer.importAnimation = false;
            importer.importCameras = false;
            importer.importLights = false;
            importer.importBlendShapes = false;
            importer.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
            importer.materialLocation = ModelImporterMaterialLocation.InPrefab;
        }

        void OnPreprocessTexture()
        {
            if (!Applies)
                return;

            var importer = (TextureImporter)assetImporter;
            var name = System.IO.Path.GetFileNameWithoutExtension(assetPath).ToLowerInvariant();
            if (name.Contains("normal") || name.EndsWith("_nrm") || name.Contains("_n."))
            {
                importer.textureType = TextureImporterType.NormalMap;
                importer.convertToNormalmap = false;
            }
            else
            {
                importer.alphaIsTransparency = true;
            }

            importer.maxTextureSize = 2048;
        }

        void OnPostprocessModel(GameObject model)
        {
            if (!Applies || model == null)
                return;

            foreach (var renderer in model.GetComponentsInChildren<Renderer>(true))
            {
                foreach (var material in renderer.sharedMaterials)
                    FixMaterial(material);
            }
        }

        static void FixMaterial(Material material)
        {
            if (material == null)
                return;

            var name = material.name.ToLowerInvariant();
            if (material.HasProperty("_BaseColor"))
                material.SetColor("_BaseColor", Color.white);
            if (material.HasProperty("_Metallic"))
                material.SetFloat("_Metallic", 0f);

            var cutout = name.Contains("hair") || name.Contains("eyebrow") || name.Contains("eyelash");
            var eyes = name.Contains("eyes");
            if (material.HasProperty("_Smoothness"))
                material.SetFloat("_Smoothness", eyes ? 0.85f : cutout ? 0.2f : 0.3f);

            if (!cutout)
                return;

            if (material.HasProperty("_Surface"))
                material.SetFloat("_Surface", 0f);
            if (material.HasProperty("_AlphaClip"))
                material.SetFloat("_AlphaClip", 1f);
            if (material.HasProperty("_Cutoff"))
                material.SetFloat("_Cutoff", 0.4f);
            if (material.HasProperty("_Cull"))
                material.SetFloat("_Cull", 0f);
            if (material.HasProperty("_SrcBlend"))
                material.SetFloat("_SrcBlend", 1f);
            if (material.HasProperty("_DstBlend"))
                material.SetFloat("_DstBlend", 0f);
            if (material.HasProperty("_ZWrite"))
                material.SetFloat("_ZWrite", 1f);
            if (material.HasProperty("_Blend"))
                material.SetFloat("_Blend", 0f);
            material.EnableKeyword("_ALPHATEST_ON");
            material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
            material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
            material.DisableKeyword("_ALPHAMODULATE_ON");
            material.SetOverrideTag("RenderType", "TransparentCutout");
            material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.AlphaTest;
        }
    }
}
#endif
